<?php
namespace Satusehat\IntegrationSdk;
final class TokenProvider {private ?string $token=null;private int $expiresAt=0;public function __construct(private Config $c){}public function invalidate():void{$this->token=null;$this->expiresAt=0;}public function get():string{if($this->token!==null&&time()<$this->expiresAt-60)return $this->token;$ch=curl_init($this->c->oauthBaseUrl().'/accesstoken?grant_type=client_credentials');curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>$this->c->timeoutSeconds,CURLOPT_HTTPHEADER=>['Content-Type: application/x-www-form-urlencoded','Accept: application/json'],CURLOPT_POSTFIELDS=>http_build_query(['client_id'=>$this->c->clientId,'client_secret'=>$this->c->clientSecret])]);$body=curl_exec($ch);if($body===false){$m=curl_error($ch);curl_close($ch);throw new \RuntimeException('OAuth transport error: '.$m);} $status=(int)curl_getinfo($ch,CURLINFO_RESPONSE_CODE);curl_close($ch);if($status<200||$status>299)throw new \RuntimeException('OAuth HTTP '.$status.': '.substr((string)$body,0,1000));$o=json_decode((string)$body,true,512,JSON_THROW_ON_ERROR);if(empty($o['access_token']))throw new \RuntimeException('OAuth response missing access_token');$this->token=(string)$o['access_token'];$this->expiresAt=time()+(int)($o['expires_in']??300);return $this->token;}}
